export const Page = Config.document('Page', {
  fields: {
    intro: Field.text('Intro', {multiline: true}),
    body: Field.richText('Body')
  }
})

import {Config, Field} from 'alinea'

export const Home = Config.document('Home', {
  fields: {
    path: Field.path('Path', {readOnly: true, width: 0.5})
  }
})

import {cms} from '@/cms'
import {Page} from '@/schema'
import {Query} from 'alinea'
import type {Metadata} from 'next'

interface PageProps {
  params: Promise<{slug?: Array<string>}>
}

export async function generateMetadata({params}: PageProps): Promise<Metadata> {
  const {slug = []} = await params
  const page = await cms.first({
    type: Page,
    url: `/${slug.join('/')}`,
    select: {title: Query.title, metadata: Page.metadata}
  })
  if (!page) return {}
  const {metadata} = page
  return {
    title: metadata.title || page.title,
    description: metadata.description,
    openGraph: {
      title: metadata.openGraph.title || metadata.title || page.title,
      description: metadata.openGraph.description || metadata.description,
      images: metadata.openGraph.image?.src
    }
  }
}
